import os from "node:os";
import fs from "node:fs";
import path from "node:path";
import { setTimeout as delay } from "node:timers/promises";

export type DoctorStatus = "pass" | "warn" | "fail" | "skip";
export interface DoctorFinding {
  id: string;
  status: DoctorStatus;
  explanation: string;
  evidence: string[];
  action?: string;
  repairAvailable: boolean;
}
export interface DoctorReport {
  schemaVersion: 1;
  findings: DoctorFinding[];
  durationMs: number;
}
export interface DoctorConfig {
  endpoint?: string;
  model?: string;
  workspace?: string;
  shell?: string;
}

const finding = (id: string, status: DoctorStatus, explanation: string, evidence: string[] = [], action?: string): DoctorFinding => ({ id, status, explanation, evidence: evidence.map(redactDiagnostic), ...(action ? { action } : {}), repairAvailable: false });

export function redactDiagnostic(value: string): string {
  return value
    .replace(/(authorization\s*:\s*(?:bearer|basic)\s+)[^\s,;]+/gi, "$1[REDACTED]")
    .replace(/((?:api[_-]?key|token|password|secret)=)[^&\s]+/gi, "$1[REDACTED]")
    .replace(/(https?:\/\/)[^/@\s]+:[^/@\s]+@/gi, "$1[REDACTED]@");
}

async function bounded<T>(fn: (signal: AbortSignal) => Promise<T>, timeoutMs = 1800): Promise<T> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try { return await fn(controller.signal); } finally { clearTimeout(timer); }
}

export async function runDoctor(config?: DoctorConfig, configError?: unknown): Promise<DoctorReport> {
  const started = Date.now();
  const findings: DoctorFinding[] = [];
  findings.push(finding("runtime.compatibility", Number(process.versions.node.split(".")[0]) >= 20 ? "pass" : "fail", `Node.js ${process.versions.node}`, [], "Upgrade Node.js to version 20 or later."));
  if (configError) findings.push(finding("config.valid", "fail", "Configuration could not be loaded.", [String(configError)], "Correct the reported configuration problem and rerun doctor."));
  else findings.push(finding("config.valid", "pass", "Configuration was loaded successfully."));
  const executable = process.argv[0];
  findings.push(finding("runtime.executable", executable ? "pass" : "warn", executable ? "Runtime executable is resolved." : "Runtime executable is unavailable.", executable ? [executable] : [], "Run Nexus from a supported Node.js installation."));
  const workspace = config?.workspace ?? process.cwd();
  try { await fs.promises.access(workspace, fs.constants.R_OK | fs.constants.W_OK); findings.push(finding("workspace.access", "pass", "Workspace is readable and writable.", [workspace])); }
  catch (error) { findings.push(finding("workspace.access", "fail", "Workspace is not accessible.", [String(error)], "Check the workspace path and permissions.")); }
  const state = path.join(os.homedir(), ".nexus");
  try { await fs.promises.access(os.homedir(), fs.constants.R_OK | fs.constants.W_OK); findings.push(finding("state.access", "pass", "Home directory for Nexus state is accessible.", [state])); }
  catch (error) { findings.push(finding("state.access", "warn", "Home directory may not permit Nexus state access.", [String(error)], "Check home-directory permissions.")); }
  const shell = config?.shell ?? process.env.SHELL ?? (process.platform === "win32" ? "cmd.exe" : "sh");
  findings.push(finding("shell.configured", shell ? "pass" : "warn", shell ? "A shell is configured." : "No shell is configured.", shell ? [shell] : [], "Configure a supported shell."));
  if (config?.endpoint) {
    try {
      const response = await bounded(async (signal) => fetch(new URL("/models", config.endpoint!), { signal, headers: { ...(process.env.OPENAI_API_KEY ? { Authorization: `Bearer ${process.env.OPENAI_API_KEY}` } : {}) } }));
      const status = response.status === 401 || response.status === 403 ? "fail" : response.ok ? "pass" : "warn";
      findings.push(finding("endpoint.connectivity", status, status === "pass" ? "Endpoint responded to a model-catalog request; inference was not tested." : `Endpoint returned HTTP ${response.status}.`, [`HTTP ${response.status}`, ...(config.model ? [`Configured model: ${config.model}`] : [])], status === "fail" ? "Verify credentials and endpoint access." : undefined));
      await response.body?.cancel();
    } catch (error) {
      findings.push(finding("endpoint.connectivity", "fail", "Endpoint could not be reached within the diagnostic limit.", [String(error)], "Verify the endpoint URL and network availability."));
    }
  } else findings.push(finding("endpoint.connectivity", "skip", "No endpoint was available for a connectivity check."));
  findings.push(finding("engine.readiness", "skip", "Engine readiness is not independently discoverable by this CLI check."));
  findings.push(finding("extensions.configured", "skip", "Configured MCP and plugin processes are not started during default diagnostics."));
  void delay;
  return { schemaVersion: 1, findings, durationMs: Date.now() - started };
}

export function renderDoctorJson(report: DoctorReport): string { return JSON.stringify(report, null, 2); }
export function renderDoctorText(report: DoctorReport): string {
  return report.findings.map((item) => `${item.status.toUpperCase()} ${item.id}: ${item.explanation}${item.action ? `\n  Next: ${item.action}` : ""}${item.evidence.length ? `\n  Evidence: ${item.evidence.join("; ")}` : ""}`).join("\n");
}
export function doctorExitCode(report: DoctorReport): number {
  if (report.findings.some((item) => item.status === "fail")) return 2;
  if (report.findings.some((item) => item.status === "warn")) return 1;
  return 0;
}
