export interface SidecarOptions {
  app: ApplicationCore;
  /** Receives complete protocol lines (each ends with "\n"). */
  write: (line: string) => void;
  mode: "auto" | "review";
  onShutdown?: () => void;
  /** Session to continue: an id, or "latest". */
  resume?: string;
  /** Prompt history file; defaults to ~/.nexus_history. */
