}

/** Drives one ApplicationCore from protocol commands and reports its activity as protocol events. */
export class SidecarServer {
  private readonly app: ApplicationCore;
  private readonly write: (line: string) => void;
  private readonly onShutdown: () => void;
  private mode: "auto" | "review";
  private alwaysApprove = false;
  private activeTurn?: Promise<void>;
  private turnAbort?: AbortController;
  private pendingApproval?: { id: string; settle: (approved: boolean) => void };
  private approvalSeq = 0;
  private shutdownPromise?: Promise<void>;
  private readonly resume?: string;
  private readonly history: string[];
  private sessionId: string;
  private checkpointManager: CheckpointManager;
  /** The running slash command; undefined for prompt turns and for commands that became turns. */
  private activeSpec?: SlashSpec;
  private readonly evidence = new EvidenceLedger();
  private lastTurn: LastTurn | null = null;

  constructor(options: SidecarOptions) {
    this.app = options.app;
    this.write = options.write;
    this.mode = options.mode;
    this.onShutdown = options.onShutdown ?? (() => {});
    this.resume = options.resume;
    this.checkpointManager = this.app.getCheckpointManager();
    this.sessionId = this.app.getSessionManager().generateSessionId();
    this.history = loadPromptHistory(options.historyFile ?? path.join(os.homedir(), ".nexus_history"));
  }

  start(): void {
    this.emit({ type: "hello", protocol: PROTOCOL_VERSION, pid: process.pid, commands: slashCatalog() });
    let resumed: { ok: boolean; message: string } | undefined;
    try {
      resumed = this.resume ? this.resumeSession(this.resume) : undefined;
    } catch (err) {
      resumed = { ok: false, message: `Could not resume ${this.resume}: ${redactSecrets(errorText(err))}` };
    }
    this.emitSessionState();
    if (resumed) this.emit({ type: "notice", text: resumed.message });
  }

  /** Resolves once no turn is running. */
  async idle(): Promise<void> {
    while (this.activeTurn) await this.activeTurn;
  }

  async handleLine(line: string): Promise<void> {
    if (!line.trim()) return;
    let command: SidecarCommand;
    try {
      command = parseCommand(line);
    } catch (err) {
      const id = err instanceof ProtocolError ? err.id : undefined;
      this.emit({ type: "error", ...(id ? { id } : {}), code: "BAD_REQUEST", message: (err as Error).message });
      return;
    }
    switch (command.type) {
      case "prompt.submit":
        this.submit(command.id, command.text);
        return;
      case "cancel":
        this.cancel();
        return;
      case "approve":
        this.resolveApproval(command.id, true, command.always);
        return;
      case "deny":
        this.resolveApproval(command.id, false, false);
        return;
      case "slash":
        this.slash(command.id, command.command, command.args);
        return;
      case "tool.detail":
      case "receipt":
        try {
          if (command.type === "tool.detail") this.toolDetail(command.id, command.evidence);
          else this.emit({ type: "receipt", id: command.id, sections: this.receipt() });
        } catch (err) {
          const message = capText(redactSecrets(stripEscapes((err as Error).message ?? String(err))));
          this.emit({ type: "error", id: command.id, code: "INTERNAL", message });
        }
        return;
      case "models.list":
        void this.modelsList(command.id);
        return;
      case "model.select":
        this.modelSelect(command.id, command.provider, command.model);
        return;
      case "provider.connect":
        void this.providerConnect(command.id, command.provider, command.method, command.key);
        return;
      case "provider.cancel":
        this.signIns.get(command.id)?.cancel();
        return;
      case "provider.disconnect": {
        const r = disconnect(command.provider);
        this.emit({ type: "provider.result", id: command.id, provider: command.provider, success: r.ok, message: r.message });
        return;
      }
      case "shutdown":
        await this.shutdown();
        return;
    }
  }

  /** Sign-ins in progress, by request id (provider.cancel stops one). */
  private signIns = new Map<string, { cancel(): void }>();

  private async modelsList(id: string): Promise<void> {
    try {
      const catalog = await buildCatalog(this.app.getConfig());
      this.emit({ type: "models.catalog", id, ...catalog });
    } catch (err) {
      this.emit({ type: "error", id, code: "INTERNAL", message: capText(redactSecrets(String((err as Error).message ?? err))) });
    }
  }

  /** Switching models between turns is the operator's choice; during a turn it is refused like any command. */
  private modelSelect(id: string, provider: string, model: string): void {
    if (this.rejectBusy(id)) return;
    const r = selectModel(this.app.getAgent(), this.app.getConfig(), { provider, model });
    this.emit({ type: "model.result", id, success: r.ok, message: r.message });
    if (r.ok) this.emitSessionState();
  }

  private async providerConnect(id: string, provider: string, method: string, key?: string): Promise<void> {
    const result = (success: boolean, message: string) =>
      this.emit({ type: "provider.result", id, provider, success, message: capText(redactSecrets(message)) });
    try {
      if (method === "api-key") {
        const r = await connectWithKey(this.app.getConfig(), provider, key ?? "");
        result(r.ok, r.message);
        return;
      }
      const signIn = await startSignIn(this.app.getConfig(), provider, method);
      this.signIns.set(id, signIn);
      this.emit({
        type: "provider.auth",
        id,
        provider,
        url: signIn.prompt.url,
        ...(signIn.prompt.userCode ? { user_code: signIn.prompt.userCode } : {}),
        instructions: signIn.prompt.instructions,
      });
      const r = await signIn.done;
      this.signIns.delete(id);
      result(r.ok, r.message);
    } catch (err) {
      this.signIns.delete(id);
      result(false, String((err as Error).message ?? err));
    }
  }

  private cancel(): void {
    const spec = this.activeSpec;
    if (this.activeTurn && spec && !spec.cancellable) {
      const name = spec.name === "!" ? "!" : `/${spec.name}`;
      this.emit({ type: "notice", text: `${name} cannot be cancelled; it finishes on its own.` });
      return;
    }
    this.turnAbort?.abort(new Error("operator cancel"));
  }

  /** Reports BUSY for `id` when a turn or command is running or the sidecar is shutting down. */
  private rejectBusy(id: string): boolean {
    if (!this.shutdownPromise && !this.activeTurn) return false;
    const message = this.shutdownPromise ? "The sidecar is shutting down." : "A turn or command is running; cancel it or wait for its result.";
    this.emit({ type: "error", id, code: "BUSY", message });
    return true;
  }

  /** Runs one turn or command as the session's only activity. Busy is reported before `body` starts. */
  private runJob(id: string, spec: SlashSpec | undefined, body: (signal: AbortSignal) => Promise<void>): void {
    const abort = new AbortController();
    this.turnAbort = abort;
    this.activeSpec = spec;
    let settle!: () => void;
    this.activeTurn = new Promise<void>((resolve) => {
      settle = resolve;
    });
    this.emitSessionState();
    void body(abort.signal)
      .catch((err) => this.emit({ type: "error", id, code: "INTERNAL", message: redactSecrets(errorText(err)) }))
      .finally(() => {
        this.activeTurn = undefined;
        this.turnAbort = undefined;
        this.activeSpec = undefined;
        this.emitSessionState();
        settle();
      });
  }

  private submit(id: string, text: string): void {
    if (this.rejectBusy(id)) return;
    this.history.push(text.trim());
    this.runJob(id, undefined, (signal) => this.turn(id, text, text, `Turn: ${text.slice(0, 30)}`, signal));
  }

  private observerFor(turnId: string): AgentObserver {
    const open = new Map<number, string>();
    const toolName = (tool: string) => capText(redactSecrets(stripEscapes(tool)), 200);
    return {
      onAssistantDelta: (delta) => this.emit({ type: "assistant.delta", turn_id: turnId, text: redactSecrets(delta) }),
      onToolStart: ({ dispatch, callId, tool: rawTool, args }) => {
        const tool = toolName(rawTool);
        const subject = toolSubject(args);
        const evidence = this.evidence.start(turnId, tool, subject, args);
        open.set(dispatch, evidence);
        this.emit({ type: "tool.start", turn_id: turnId, call_id: callId, tool, subject, evidence });
      },
      onToolEnd: ({ dispatch, callId, tool: rawTool, success, output, error }) => {
        const tool = toolName(rawTool);
        const evidence = open.get(dispatch) ?? "";
        open.delete(dispatch);
        this.evidence.end(evidence, success, output, error);
        this.emit({ type: "tool.end", turn_id: turnId, call_id: callId, tool, success, evidence, ...toolSummary(success, output, error) });
      },
      onProviderRecovery: ({ record, discardedPartialOutput }) => {
        const text = providerRecoveryNotice(record, discardedPartialOutput);
        if (text) this.emit({ type: "notice", text });
      },
    };
  }

  private confirmFor(turnId: string, signal: AbortSignal) {
    return this.mode === "review"
      ? (tool: string, args: Record<string, any>) => this.requestApproval(turnId, signal, tool, args)
      : undefined;
  }

  /** One agent turn: checkpoint, run, save the session, report the result. */
  private async turn(turnId: string, prompt: string | any[], label: string, checkpoint: string, signal: AbortSignal): Promise<void> {
    try {
      this.checkpointManager.createCheckpoint(checkpoint);
    } catch (err) {
      const message = `No checkpoint could be saved, so the turn did not start: ${redactSecrets(errorText(err))}`;
      this.emit({ type: "error", id: turnId, code: "INTERNAL", message });
      return;
    }
    const agent = this.app.getAgent();
    agent.setObserver(this.observerFor(turnId));
    // Work done so far, and changes still awaiting verification, survive the process ending mid-turn.
    agent.setProgressListener(() => this.saveSession(label));
    let turn: TurnResult;
    try {
      turn = await agent.runTurn(prompt, this.confirmFor(turnId, signal), { signal });
    } catch (err) {
      turn = failedTurnFromError(err, this.app.getConfig().maxSteps);
    } finally {
      agent.setObserver(undefined);
      agent.setProgressListener(undefined);
    }
    try {
      this.saveSession(label, turn);
    } catch (err) {
      this.emit({ type: "notice", text: `The session could not be saved: ${redactSecrets(errorText(err))}` });
    }
    const { heading, line } = summarizeTurn(turn);
    const projected = projectTurn(turn);
    this.lastTurn = { heading, turn: projected };
    const summary = turn.execution === "COMPLETED" ? agent.getCompletionSummary() : undefined;
    this.emit({
      type: "turn.result",
      turn_id: turnId,
      heading,
      line: redactSecrets(line),
      turn: projected,
      model_summary: summary
        ? { summary: redactSecrets(summary.summary), ...(summary.notes ? { notes: redactSecrets(summary.notes) } : {}) }
        : null,
    });
  }

  private requestApproval(turnId: string, signal: AbortSignal, tool: string, args: Record<string, any>): Promise<boolean> {
    if (this.alwaysApprove) return Promise.resolve(true);
    if (signal.aborted) return Promise.resolve(false);
    const id = `approval-${++this.approvalSeq}`;
    return new Promise<boolean>((resolve) => {
      const onAbort = () => settle(false);
      const settle = (approved: boolean) => {
        signal.removeEventListener("abort", onAbort);
        this.pendingApproval = undefined;
        resolve(approved);
      };
      signal.addEventListener("abort", onAbort, { once: true });
      this.pendingApproval = { id, settle };
      this.emit({
        type: "approval.request",
        id,
        turn_id: turnId,
        tool,
        subject: toolSubject(args),
        preview: capText(redactedJson(args)),
        review: approvalReview(tool, args, this.app.getConfig().workspace),
      });
    });
  }

  private resolveApproval(id: string, approved: boolean, always: boolean): void {
    const pending = this.pendingApproval;
    if (!pending || pending.id !== id) {
      this.emit({ type: "error", id, code: "NO_PENDING_APPROVAL", message: `No pending approval with id ${id}.` });
      return;
    }
    if (approved && always) {
      this.alwaysApprove = true;
      this.mode = "auto";
      this.emitSessionState();
    }
    pending.settle(approved);
  }

  private slash(id: string, command: string, args: string): void {
    if (this.rejectBusy(id)) return;
    this.runJob(id, findSlash(command), async (signal) => {
      const agent = this.app.getAgent();
      agent.setObserver(this.observerFor(id));
      let outcome: SlashOutcome;
      try {
        outcome = await routeSlash(this.slashHost(id), command, args, signal);
      } finally {
        agent.setObserver(undefined);
      }
      if (outcome.kind === "turn") {
        this.activeSpec = undefined;
        this.emit({ type: "slash.result", id, command: outcome.command, success: true, output: "", prompt: capText(redactSecrets(stripEscapes(outcome.label))) });
        await this.turn(id, outcome.prompt, outcome.label, outcome.checkpoint, signal);
        return;
      }
      if (outcome.command === "clear" && outcome.success) this.lastTurn = null;
      this.emit({
        type: "slash.result",
        id,
        command: outcome.command,
        success: outcome.success,
        output: capText(redactSecrets(stripEscapes(outcome.output)), MAX_SLASH_OUTPUT),
        ...(outcome.format ? { format: outcome.format } : {}),
        ...(outcome.composer !== undefined ? { composer: outcome.composer } : {}),
      });
    });
  }

  private slashHost(id: string): SlashHost {
    return {
      app: this.app,
      mode: () => this.mode,
      setMode: (mode) => {
        this.mode = mode;
        if (mode === "review") this.alwaysApprove = false;
      },
      sessionId: () => this.sessionId,
      setSessionId: (sessionId) => {
        this.sessionId = sessionId;
      },
      checkpoints: () => this.checkpointManager,
      setWorkspace: (dir) => this.setWorkspace(dir),
      saveSession: (title) => this.saveSession(title),
      resumeSession: (sessionId) => this.resumeSession(sessionId),
      history: () => this.history,
      confirm: (signal) => this.confirmFor(id, signal),
      receipt: () => this.receipt(),
    };
  }

  private toolDetail(id: string, evidence: string): void {
    const record = this.evidence.get(evidence);
    if (!record) {
      const message = `No record of tool call ${capText(redactSecrets(stripEscapes(evidence)))}; only the latest ${MAX_EVIDENCE} are kept.`;
      this.emit({ type: "error", id, code: "NOT_FOUND", message });
      return;
    }
    this.emit({
      type: "tool.detail",
      id,
      evidence,
      tool: record.tool,
      subject: record.subject,
      status: record.status,
      args: record.args,
      output: record.output,
      duration_ms: record.durationMs,
    });
  }

  private receipt(): ReceiptSection[] {
    return receiptSections(this.lastTurn, this.app.getActiveValidationReceipt());
  }

  private setWorkspace(dir: string): void {
    this.app.getAgent().setWorkspace(dir);
    this.app.getConfig().workspace = dir;
    this.checkpointManager = new CheckpointManager(dir);
  }

  /** Same record the REPL saves after each turn. Skipped while the conversation holds only the system prompt. */
  private saveSession(title?: string, turn?: TurnResult): void {
    const agent = this.app.getAgent();
    const messages = agent.getMessages();
    if (messages.length <= 1) return;
    const config = this.app.getConfig();
    const now = new Date().toISOString();
    this.app.getSessionManager().saveSession(
      {
        id: this.sessionId,
        title: title ? title.slice(0, 60).replace(/\n/g, " ") : "Active Session",
        createdAt: now,
        updatedAt: now,
        workspace: config.workspace,
        model: config.model,
        messages,
        unverifiedChangesPending: agent.hasUnverifiedChanges(),
        tokenStats: agent.getTokenStats(),
        ...(turn ? { status: lifecycleStatusForTurn(turn), lastTurn: turn } : {}),
      },
      agent.getWorkspacePathIdentity(),
    );
  }

  private resumeSession(id?: string): { ok: boolean; message: string } {
    const manager = this.app.getSessionManager();
    const session = !id || id === "latest" ? manager.getLatestSession() : manager.loadSession(id);
    if (!session) return { ok: false, message: `Session not found: ${id || "latest"}` };
    if (!Array.isArray(session.messages)) return { ok: false, message: `Session ${session.id} is unreadable: it has no message list.` };
    if (session.workspace && fs.existsSync(session.workspace)) this.setWorkspace(session.workspace);
    this.sessionId = session.id;
    this.app.getAgent().restoreSession(session.messages, session.unverifiedChangesPending);
    this.lastTurn = null;
    return { ok: true, message: `Resumed session ${session.id} (${session.messages.length} messages).` };
  }

  private shutdown(): Promise<void> {
    for (const signIn of this.signIns.values()) signIn.cancel();
    this.signIns.clear();
    this.shutdownPromise ??= (async () => {
      this.turnAbort?.abort(new Error("sidecar shutdown"));
      await this.idle();
      this.app.shutdown();
      this.onShutdown();
    })();
    return this.shutdownPromise;
  }

  private emitSessionState(): void {
    const config = this.app.getConfig();
    const git = getGitInfo(config.workspace);
    this.emit({
      type: "session.state",
      workspace: config.workspace,
      workspace_name: path.basename(config.workspace),
      model: config.provider ? `${config.provider} · ${config.model}` : config.model,
      mode: this.mode,
      git: git.isRepo ? { branch: git.branch, dirty: git.dirtyCount } : null,
      busy: Boolean(this.activeTurn),
    });
  }

  private emit(event: SidecarEvent): void {
    this.write(encodeEvent(event));
  }
}

/** Prompt history from the REPL's file, redacted; empty when the file is missing or unreadable. */
function loadPromptHistory(file: string): string[] {
  try {
    return redactForPersistence(fs.readFileSync(file, "utf-8"))
      .split("\n")
      .filter((line) => line.trim());
  } catch {
    return [];
  }
}

/**
 * Process entry point. Stdout is reserved for protocol lines: the real writer is captured first, then every
 * other stdout write (agent banners, spinners, console.log) is dropped, or sent to stderr with NEXUS_DEBUG=1.
 */
async function main(argv: string[]): Promise<void> {
  const protocolWrite = process.stdout.write.bind(process.stdout);
  const debug = process.env.NEXUS_DEBUG === "1";
  (process.stdout as any).write = (chunk: unknown, encoding?: unknown, cb?: unknown): boolean => {
    if (debug) process.stderr.write(typeof chunk === "string" ? chunk : Buffer.from(chunk as Uint8Array));
    const done = typeof encoding === "function" ? encoding : cb;
    if (typeof done === "function") (done as () => void)();
    return true;
  };
  const toStderr = (...args: unknown[]): void => {
    if (debug) process.stderr.write(args.map((a) => (typeof a === "string" ? a : JSON.stringify(a))).join(" ") + "\n");
  };
  console.log = toStderr;
  console.info = toStderr;
  console.warn = toStderr;
  console.debug = toStderr;

  loadEnvironment();
  const program = new Command()
    .name("nexus-sidecar")
    .option("-e, --endpoint <url>", "Local LLM endpoint")
    .option("-m, --model <name>", "Model name")
    .option("-w, --workspace <path>", "Workspace directory")
    .option("-s, --max-steps <number>", "Maximum steps per turn")
    .option("-t, --temperature <number>", "Model temperature")
    .option("--shell <type>", "Shell for commands", "bash")
    .option("--fallback <urls>", "Comma-separated fallback LLM endpoints")
    .option("--context-limit <tokens>", "Model context window limit in tokens")
    .option("--dry-run", "Simulate file modifications without writing changes to disk")
    .option("--read-only", "Reject all mutating tool executions and commands")
    .option("--sandbox [mode]", "Isolate command execution using bubblewrap or Docker")
    .option("--worktree", "Isolate execution inside an ephemeral git worktree")
    .option("--authoritative-verifier <command>", "Trusted command whose success may authorize automatic worktree merge")
    .option("--record-flight", "Record execution into an append-only .flightlog")
    .option("--planner-model <name>", "Deep reasoning model for planning")
    .option("--planner-endpoint <url>", "Inference endpoint for the planner model")
    .option("--coder-model <name>", "Model for code implementation")
    .option("--coder-endpoint <url>", "Inference endpoint for the coder model")
    .option("--approve", "Require operator approval before edits and shell commands")
    .option("-r, --resume [id]", "Resume a saved session (the latest when no id is given)")
    .parse(argv);
  const options = program.opts();
  const config = await autoDetectModel(buildConfig(options));
  const app = new ApplicationCore(config);
  const server = new SidecarServer({
    app,
    mode: options.approve ? "review" : "auto",
    resume: typeof options.resume === "string" ? options.resume : options.resume ? "latest" : undefined,
    write: (line) => {
      protocolWrite(line);
    },
    onShutdown: () => process.exit(0),
  });

  const report = (err: unknown) => process.stderr.write(`nexus sidecar: ${err instanceof Error ? err.message : String(err)}\n`);
  const input = readline.createInterface({ input: process.stdin, crlfDelay: Infinity });
  input.on("line", (line) => {
    server.handleLine(line).catch(report);
  });
  const requestShutdown = () => {
    server.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "shutdown" })).catch(report);
  };
  input.on("close", requestShutdown);
  process.stdout.on("error", requestShutdown);
  server.start();
}

/** True when argv[1] names this module, comparing real paths so a symlinked launcher still counts. */
function isEntryPoint(argv1: string | undefined, moduleUrl: string): boolean {
  if (!argv1) return false;
  try {
    return fs.realpathSync(path.resolve(argv1)) === fs.realpathSync(fileURLToPath(moduleUrl));
  } catch {
    return false;
  }
}

if (isEntryPoint(process.argv[1], import.meta.url)) {
  main(process.argv).catch((err) => {
    process.stderr.write(`nexus sidecar failed to start: ${err instanceof Error ? err.message : String(err)}\n`);
    process.exit(1);
  });
}

/**
 * Nexus sidecar protocol v1: newline-delimited JSON between the Ratatui client (parent) and the
 * Node agent sidecar (child). The sidecar projects agent state; it never asks the client to decide outcomes.
 */
import type { ProviderRecoveryRecord, TurnResult } from "./core/turn.js";
import { redactSecrets } from "./ui.js";
import type { ApprovalReview } from "./approval_review.js";
import type { SlashSpec } from "./slash/catalog.js";
import type { EvidenceStatus, ReceiptSection } from "./evidence.js";
import type { Catalog } from "./model_catalog.js";

export const PROTOCOL_VERSION = 1;
export const MAX_TEXT_FIELD = 8000;
export const MAX_SUMMARY = 160;
export const MAX_SLASH_OUTPUT = 32_000;

export type ErrorCode = "BAD_REQUEST" | "BUSY" | "NO_PENDING_APPROVAL" | "NOT_FOUND" | "INTERNAL";

export interface ModelSummary {
  summary: string;
  notes?: string;
}

export type SidecarEvent =
  | { type: "hello"; protocol: number; pid: number; commands: Array<Pick<SlashSpec, "name" | "usage" | "summary">> }
  | {
      type: "session.state";
      workspace: string;
      workspace_name: string;
      model: string;
      mode: "auto" | "review";
      git: { branch: string; dirty: number } | null;
      busy: boolean;
    }
  | { type: "assistant.delta"; turn_id: string; text: string }
  | { type: "tool.start"; turn_id: string; call_id: string; tool: string; subject: string; evidence: string }
  | { type: "tool.end"; turn_id: string; call_id: string; tool: string; success: boolean; summary: string; lines: number; evidence: string }
  | { type: "approval.request"; id: string; turn_id: string; tool: string; subject: string; preview: string; review: ApprovalReview }
  | { type: "turn.result"; turn_id: string; heading: string; line: string; turn: TurnResult; model_summary: ModelSummary | null }
  | {
      type: "slash.result";
      id: string;
      command: string;
      success: boolean;
      output: string;
      /** "diff": colour unified-diff lines. */
      format?: "diff";
      /** Text for the client to put into the composer. */
      composer?: string;
      /** The command started a turn with this prompt; the turn's events follow under the same id. */
      prompt?: string;
    }
  | { type: "notice"; text: string }
  | {
      type: "tool.detail";
      id: string;
      evidence: string;
      tool: string;
      subject: string;
      status: EvidenceStatus;
      args: string;
      output: string;
      duration_ms: number | null;
    }
  | { type: "receipt"; id: string; sections: ReceiptSection[] }
  | { type: "error"; id?: string; code: ErrorCode; message: string }
  /** Answer to models.list: providers (with connection source, never a credential), models, current and recent. */
  | ({ type: "models.catalog"; id: string } & Catalog)
  /** A sign-in needs the operator: open `url` (and type `user_code` for a device flow). */
  | { type: "provider.auth"; id: string; provider: string; url: string; user_code?: string; instructions: string }
  /** Outcome of provider.connect / provider.disconnect. */
  | { type: "provider.result"; id: string; provider: string; success: boolean; message: string }
  /** Outcome of model.select. */
  | { type: "model.result"; id: string; success: boolean; message: string };

export type SidecarCommand =
  | { type: "prompt.submit"; id: string; text: string }
  | { type: "cancel" }
  | { type: "approve"; id: string; always: boolean }
  | { type: "deny"; id: string }
  | { type: "slash"; id: string; command: string; args: string }
  | { type: "tool.detail"; id: string; evidence: string }
  | { type: "receipt"; id: string }
  | { type: "models.list"; id: string }
  | { type: "model.select"; id: string; provider: string; model: string }
  /** `key` only for method "api-key"; it is never echoed back or logged. */
  | { type: "provider.connect"; id: string; provider: string; method: string; key?: string }
  | { type: "provider.cancel"; id: string }
  | { type: "provider.disconnect"; id: string; provider: string }
  | { type: "shutdown" };

export class ProtocolError extends Error {
  constructor(message: string, public readonly id?: string) {
    super(message);
    this.name = "ProtocolError";
  }
}

const LONE_SURROGATE = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g;

/** Truncation can split a surrogate pair; a lone surrogate would serialize as JSON the client cannot decode. */
export function encodeEvent(event: SidecarEvent): string {
  const wellFormed = (_key: string, value: unknown) => (typeof value === "string" ? value.replace(LONE_SURROGATE, "\uFFFD") : value);
  return JSON.stringify({ v: PROTOCOL_VERSION, ...event }, wellFormed) + "\n";
}

export function parseCommand(line: string): SidecarCommand {
  let raw: unknown;
  try {
    raw = JSON.parse(line);
  } catch {
    throw new ProtocolError("line is not valid JSON");
  }
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new ProtocolError("message must be a JSON object");
  const msg = raw as Record<string, unknown>;
  const id = typeof msg.id === "string" && msg.id ? msg.id : undefined;
  if (msg.v !== PROTOCOL_VERSION) throw new ProtocolError(`unsupported protocol version: ${String(msg.v)}`, id);
  const requireId = (type: string): string => {
    if (!id) throw new ProtocolError(`${type} requires id`);
    return id;
  };
  switch (msg.type) {
    case "prompt.submit": {
      const requestId = requireId("prompt.submit");
      const text = msg.text;
      if (typeof text !== "string" || !text.trim()) throw new ProtocolError("prompt.submit requires non-empty text", requestId);
      return { type: "prompt.submit", id: requestId, text };
    }
    case "cancel":
      return { type: "cancel" };
    case "approve":
      return { type: "approve", id: requireId("approve"), always: msg.always === true };
    case "deny":
      return { type: "deny", id: requireId("deny") };
    case "slash": {
      const requestId = requireId("slash");
      const command = msg.command;
      if (typeof command !== "string" || !command.trim()) throw new ProtocolError("slash requires command", requestId);
      return { type: "slash", id: requestId, command, args: typeof msg.args === "string" ? msg.args : "" };
    }
    case "tool.detail": {
      const requestId = requireId("tool.detail");
      const evidence = msg.evidence;
      if (typeof evidence !== "string" || !evidence) throw new ProtocolError("tool.detail requires evidence", requestId);
      return { type: "tool.detail", id: requestId, evidence };
    }
    case "receipt":
      return { type: "receipt", id: requireId("receipt") };
    case "models.list":
      return { type: "models.list", id: requireId("models.list") };
    case "model.select": {
      const requestId = requireId("model.select");
      if (typeof msg.provider !== "string" || !msg.provider || typeof msg.model !== "string" || !msg.model.trim()) {
        throw new ProtocolError("model.select requires provider and model", requestId);
      }
      return { type: "model.select", id: requestId, provider: msg.provider, model: msg.model };
    }
    case "provider.connect": {
      const requestId = requireId("provider.connect");
      if (typeof msg.provider !== "string" || !msg.provider || typeof msg.method !== "string" || !msg.method) {
        throw new ProtocolError("provider.connect requires provider and method", requestId);
      }
      if (msg.key !== undefined && typeof msg.key !== "string") throw new ProtocolError("provider.connect key must be a string", requestId);
      return { type: "provider.connect", id: requestId, provider: msg.provider, method: msg.method, ...(typeof msg.key === "string" ? { key: msg.key } : {}) };
    }
    case "provider.cancel":
      return { type: "provider.cancel", id: requireId("provider.cancel") };
    case "provider.disconnect": {
      const requestId = requireId("provider.disconnect");
      if (typeof msg.provider !== "string" || !msg.provider) throw new ProtocolError("provider.disconnect requires provider", requestId);
      return { type: "provider.disconnect", id: requestId, provider: msg.provider };
    }
    case "shutdown":
      return { type: "shutdown" };
    default:
      throw new ProtocolError(`unknown message type: ${String(msg.type)}`, id);
  }
}

export function capText(text: string, max: number = MAX_TEXT_FIELD): string {
  if (text.length <= max) return text;
  return `${text.slice(0, max)}…[truncated ${text.length - max} chars]`;
}

/** CSI sequences, OSC sequences (BEL or ST terminated), then the remaining two-character escapes. */
const TERMINAL_ESCAPE = /\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[ -/]*[0-~]/g;

export function stripEscapes(text: string): string {
  return text.replace(TERMINAL_ESCAPE, "");
}

export function toolSubject(args: Record<string, any>): string {
  const subject = args.path ?? args.file_path ?? args.command ?? args.url ?? args.query ?? args.name ?? "";
  return redactSecrets(stripEscapes(String(subject))).replace(/\s+/g, " ").trim().slice(0, 200);
}

/** Copy of a turn with secrets redacted from its free-text fields; enums, counts, ids and hashes are left as-is. */
export function projectTurn(turn: TurnResult): TurnResult {
  const redactOptional = (text: string | undefined) => (text === undefined ? undefined : redactSecrets(text));
  return {
    ...turn,
    detail: redactOptional(turn.detail),
    verification: turn.verification ? { ...turn.verification, command: redactOptional(turn.verification.command) } : null,
    interruption: turn.interruption ? { ...turn.interruption, outstandingTool: redactOptional(turn.interruption.outstandingTool) } : null,
    inferenceFailure: turn.inferenceFailure ? { ...turn.inferenceFailure, message: redactSecrets(turn.inferenceFailure.message) } : null,
    ...(turn.providerRecovery
      ? {
          providerRecovery: turn.providerRecovery.map((r) => ({
            ...r,
            reason: redactOptional(r.reason),
            submissions: r.submissions.map((s) => ({ ...s, message: redactSecrets(s.message) })),
          })),
        }
      : {}),
  };
}

/** One-line operator notice for a provider recovery transition; PROBING produces none. */
export function providerRecoveryNotice(record: ProviderRecoveryRecord, discardedPartialOutput: boolean): string | undefined {
  const last = record.submissions[record.submissions.length - 1];
  const condition = record.condition.toLowerCase().replace(/_/g, " ");
  const discarded = discardedPartialOutput ? " The partial response was discarded." : "";
  switch (record.state) {
    case "WAITING": {
      const secs = record.nextAttemptAt ? Math.max(0, Math.round((Date.parse(record.nextAttemptAt) - Date.parse(record.updatedAt)) / 1000)) : 0;
      return `Inference provider ${condition} (${last?.httpStatus ? `HTTP ${last.httpStatus}` : last?.kind ?? "failure"}); waiting ${secs}s before checking again. Work is preserved.${discarded}`;
    }
    case "RESUMED":
      return `Inference provider recovered after ${Math.round(record.waitedMs / 1000)}s; step ${record.step} resumed.`;
    case "PROBING":
      return undefined;
    default:
      return redactSecrets(`Provider recovery ${record.state.toLowerCase()}: ${record.reason ?? condition}`);
  }
}

export function toolSummary(success: boolean, output: string, error?: string): { summary: string; lines: number } {
  const text = redactSecrets(stripEscapes(success ? output || "" : error || output || "")).trim();
  const first = text.split(/\r?\n/).find((line) => line.trim())?.trim() ?? (success ? "Completed" : "Tool failed");
  return { summary: first.replace(/\s+/g, " ").slice(0, MAX_SUMMARY), lines: text ? text.split(/\r?\n/).length : 0 };
}
//! Client side of the Nexus sidecar protocol v1 (`cli/src/protocol.ts`). The sidecar is the authority on every
//! outcome; these types carry what it reports and nothing more.
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::fmt;

pub const PROTOCOL_VERSION: u64 = 1;

#[derive(Clone, Debug, Deserialize, PartialEq)]
pub struct GitInfo {
    pub branch: String,
    pub dirty: u64,
}

#[derive(Clone, Debug, Deserialize, PartialEq)]
pub struct ModelSummary {
    pub summary: String,
    #[serde(default)]
    pub notes: Option<String>,
}

/// One entry of the slash-command catalogue the sidecar announces in `hello`.
#[derive(Clone, Debug, Deserialize, PartialEq)]
pub struct SlashSpec {
    pub name: String,
    pub usage: String,
    pub summary: String,
}

/// A way to connect a provider: an API key, a browser sign-in, or a device-code sign-in.
#[derive(Clone, Debug, Deserialize, PartialEq)]
pub struct ConnectMethod {
    pub id: String,
    pub label: String,
    pub kind: String,
    /// Signs in as another vendor's client; the provider's terms may not permit it.
    #[serde(default)]
    pub unofficial: bool,
}

/// A provider as the model picker shows it. `source` names where its credential comes from, never the credential.
#[derive(Clone, Debug, Deserialize, PartialEq)]
pub struct CatalogProvider {
    pub id: String,
    pub label: String,
    pub disclosure: String,
    pub connected: bool,
    #[serde(default)]
    pub source: Option<String>,
    #[serde(default)]
    pub external: bool,
    #[serde(default)]
    pub methods: Vec<ConnectMethod>,
    pub status: String,
    #[serde(default)]
    pub error: Option<String>,
}

#[derive(Clone, Debug, Deserialize, PartialEq)]
pub struct CatalogModel {
    pub provider: String,
    pub id: String,
}

#[derive(Clone, Debug, Deserialize, PartialEq)]
pub struct ModelRef {
    pub provider: String,
    pub model: String,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Catalog {
    pub providers: Vec<CatalogProvider>,
    pub models: Vec<CatalogModel>,
    pub current: ModelRef,
    pub recent: Vec<ModelRef>,
}

/// A credential typed by the operator. Serializes as the plain string; never prints.
#[derive(Clone, PartialEq, Serialize)]
#[serde(transparent)]
pub struct Secret(pub String);

impl fmt::Debug for Secret {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("Secret(***)")
    }
}

/// One block of the turn receipt: labelled rows, or a note saying why there are none.
#[derive(Clone, Debug, Deserialize, PartialEq)]
pub struct ReceiptSection {
    pub title: String,
    #[serde(default)]
    pub rows: Vec<(String, String)>,
    #[serde(default)]
    pub note: Option<String>,
}

/// What the operator is asked to approve (`approvalReview` in `cli/src/approval_review.ts`). Text is already
/// redacted and capped by the sidecar.
#[derive(Clone, Debug, Deserialize, PartialEq)]
#[serde(tag = "kind")]
pub enum Review {
    #[serde(rename = "change")]
    Change {
        path: String,
        before: Option<String>,
        after: String,
        created: bool,
        truncated: bool,
    },
    #[serde(rename = "patch")]
    Patch {
        path: String,
        patch: String,
        truncated: bool,
    },
    #[serde(rename = "command")]
    Shell { command: String },
    #[serde(rename = "args")]
    Args { text: String, truncated: bool },
    /// A review kind this client does not know; the modal still asks, without a preview.
    #[serde(other)]
    Unknown,
}

/// Sidecar → UI events. Fields this client does not use are ignored by serde.
#[derive(Clone, Debug, Deserialize, PartialEq)]
#[serde(tag = "type")]
pub enum Event {
    #[serde(rename = "hello")]
    Hello {
        protocol: u64,
        #[serde(default)]
        commands: Vec<SlashSpec>,
    },
    #[serde(rename = "session.state")]
    SessionState {
        workspace_name: String,
        model: String,
        mode: String,
        git: Option<GitInfo>,
        busy: bool,
    },
    #[serde(rename = "assistant.delta")]
    AssistantDelta { turn_id: String, text: String },
    #[serde(rename = "tool.start")]
    ToolStart {
        call_id: String,
        tool: String,
        subject: String,
        /// Handle for this call's full record in the sidecar; empty from sidecars that keep none.
        #[serde(default)]
        evidence: String,
    },
    #[serde(rename = "tool.end")]
    ToolEnd {
        call_id: String,
        tool: String,
        success: bool,
        summary: String,
    },
    #[serde(rename = "approval.request")]
    ApprovalRequest {
        id: String,
        tool: String,
        subject: String,
        #[serde(default)]
        review: Option<Review>,
    },
    #[serde(rename = "turn.result")]
    TurnResult {
        heading: String,
        line: String,
        turn: Value,
        model_summary: Option<ModelSummary>,
    },
    #[serde(rename = "slash.result")]
    SlashResult {
        id: String,
        command: String,
        success: bool,
        output: String,
        #[serde(default)]
        format: Option<String>,
        #[serde(default)]
        composer: Option<String>,
        /// Set when the command started a turn with this prompt; the turn's events follow under the same id.
        #[serde(default)]
        prompt: Option<String>,
    },
    #[serde(rename = "notice")]
    Notice { text: String },
    #[serde(rename = "tool.detail")]
    ToolDetail {
        id: String,
        status: String,
        args: String,
        output: String,

        output: String,
        #[serde(default)]
        duration_ms: Option<u64>,
    },
    #[serde(rename = "receipt")]
    Receipt {
        id: String,
        sections: Vec<ReceiptSection>,
    },
    #[serde(rename = "error")]
    Error {
        #[serde(default)]
        id: Option<String>,
        code: String,
        message: String,
    },
    #[serde(rename = "models.catalog")]
    ModelsCatalog {
        id: String,
        providers: Vec<CatalogProvider>,
        models: Vec<CatalogModel>,
        current: ModelRef,
        #[serde(default)]
        recent: Vec<ModelRef>,
    },
    /// A sign-in waits for the operator: open `url`, and type `user_code` for a device sign-in.
    #[serde(rename = "provider.auth")]
    ProviderAuth {
        id: String,
        provider: String,
        url: String,
        #[serde(default)]
        user_code: Option<String>,
        instructions: String,
    },
    #[serde(rename = "provider.result")]
    ProviderResult {
        id: String,
        provider: String,
        success: bool,
        message: String,
    },
    #[serde(rename = "model.result")]
    ModelResult {
        id: String,
        success: bool,
        message: String,
    },
    /// Event types newer than this client.
    #[serde(other)]
    Unknown,
}

/// UI → sidecar commands used by the live view.
#[derive(Clone, Debug, Serialize, PartialEq)]
#[serde(tag = "type")]
pub enum Command {
    #[serde(rename = "prompt.submit")]
    PromptSubmit { id: String, text: String },
    #[serde(rename = "cancel")]
    Cancel,
    #[serde(rename = "approve")]
    Approve { id: String, always: bool },
    #[serde(rename = "deny")]
    Deny { id: String },
    #[serde(rename = "slash")]
    Slash {
        id: String,
        command: String,
        args: String,
    },
    #[serde(rename = "tool.detail")]
    ToolDetail { id: String, evidence: String },
    #[serde(rename = "receipt")]
    Receipt { id: String },
    #[serde(rename = "models.list")]
    ModelsList { id: String },
    #[serde(rename = "model.select")]
    ModelSelect {
        id: String,
        provider: String,
        model: String,
    },
    #[serde(rename = "provider.connect")]
    ProviderConnect {
        id: String,
        provider: String,
        method: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        key: Option<Secret>,
    },
    #[serde(rename = "provider.cancel")]
    ProviderCancel { id: String },
    #[serde(rename = "provider.disconnect")]
    ProviderDisconnect { id: String, provider: String },
    #[serde(rename = "shutdown")]
    Shutdown,
}

pub fn parse_event(line: &str) -> Result<Event, String> {
    let value: Value = serde_json::from_str(line)
        .or_else(|err| serde_json::from_str(&replace_lone_surrogates(line)).map_err(|_| err))
        .map_err(|err| format!("not JSON: {err}"))?;
    if value.get("v").and_then(Value::as_u64) != Some(PROTOCOL_VERSION) {
        return Err(format!(
            "unsupported protocol version: {}",
            value.get("v").unwrap_or(&Value::Null)
        ));
    }
    serde_json::from_value(value).map_err(|err| format!("invalid event: {err}"))
}

/// The UTF-16 code unit of a `\uXXXX` escape at the start of `text`.
fn escape_unit(text: &str) -> Option<u16> {
    let hex = text.strip_prefix("\\u")?.get(..4)?;
    if !hex.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return None;
    }
    u16::from_str_radix(hex, 16).ok()
}

/// Rewrites escapes of lone UTF-16 surrogates as `\ufffd`; serde_json rejects them, and a sidecar that truncates
/// text mid-pair can emit one.
fn replace_lone_surrogates(line: &str) -> String {
    let mut out = String::with_capacity(line.len());
    let mut rest = line;
    while let Some(at) = rest.find('\\') {
        out.push_str(&rest[..at]);
        let tail = &rest[at..];
        let consumed = match escape_unit(tail) {
            Some(0xD800..=0xDBFF) if matches!(escape_unit(&tail[6..]), Some(0xDC00..=0xDFFF)) => 12,
            Some(0xD800..=0xDFFF) => {
                out.push_str("\\ufffd");
                rest = &tail[6..];
                continue;
            }
            Some(_) => 6,
            None => tail
                .char_indices()
                .nth(2)
                .map_or(tail.len(), |(index, _)| index),
        };
        out.push_str(&tail[..consumed]);
        rest = &tail[consumed..];
    }
    out.push_str(rest);
    out
}

pub fn encode_command(command: &Command) -> String {
    let mut value = serde_json::to_value(command).expect("protocol commands always serialize");
    if let Value::Object(map) = &mut value {
        map.insert("v".to_string(), Value::from(PROTOCOL_VERSION));
    }
    format!("{value}\n")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_every_rendered_event_type() {
        assert_eq!(
            parse_event(r#"{"v":1,"type":"hello","protocol":1,"pid":42}"#),
            Ok(Event::Hello {
                protocol: 1,
                commands: Vec::new()
            })
        );
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"session.state","workspace":"/w/app","workspace_name":"app","model":"m","mode":"auto","git":{"branch":"main","dirty":2},"busy":false}"#
            ),
            Ok(Event::SessionState {
                workspace_name: "app".into(),
                model: "m".into(),
                mode: "auto".into(),
                git: Some(GitInfo {
                    branch: "main".into(),
                    dirty: 2
                }),
                busy: false,
            })
        );
        assert!(matches!(
            parse_event(
                r#"{"v":1,"type":"session.state","workspace":"/w","workspace_name":"w","model":"m","mode":"review","git":null,"busy":true}"#
            ),
            Ok(Event::SessionState {
                git: None,
                busy: true,
                ..
            })
        ));
        assert_eq!(
            parse_event(r#"{"v":1,"type":"assistant.delta","turn_id":"t1","text":"hi"}"#),
            Ok(Event::AssistantDelta {
                turn_id: "t1".into(),
                text: "hi".into()
            })
        );
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"tool.start","turn_id":"t1","call_id":"c1","tool":"read_file","subject":"src/a.ts"}"#
            ),
            Ok(Event::ToolStart {
                call_id: "c1".into(),
                tool: "read_file".into(),
                subject: "src/a.ts".into(),
                evidence: String::new(),
            })
        );
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"tool.end","turn_id":"t1","call_id":"c1","tool":"read_file","success":false,"summary":"No such file","lines":1}"#
            ),
            Ok(Event::ToolEnd {
                call_id: "c1".into(),
                tool: "read_file".into(),
                success: false,
                summary: "No such file".into()
            })
        );
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"approval.request","id":"approval-1","turn_id":"t1","tool":"write_file","subject":"x.txt","preview":"{}"}"#
            ),
            Ok(Event::ApprovalRequest {
                id: "approval-1".into(),
                tool: "write_file".into(),
                subject: "x.txt".into(),
                review: None,
            })
        );
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"error","id":"t2","code":"BUSY","message":"A turn is already running"}"#
            ),
            Ok(Event::Error {
                id: Some("t2".into()),
                code: "BUSY".into(),
                message: "A turn is already running".into()
            })
        );
    }

    #[test]
    fn turn_result_keeps_the_reported_turn_verbatim() {
        let event = parse_event(r#"{"v":1,"type":"turn.result","turn_id":"t1","heading":"TURN INTERRUPTED","line":"Stopped by operator","turn":{"execution":"INTERRUPTED","outcome":"NOT_ESTABLISHED"},"model_summary":null}"#).unwrap();
        let Event::TurnResult {
            heading,
            line,
            turn,
            model_summary,
        } = event
        else {
            panic!("expected turn.result");
        };
        assert_eq!(heading, "TURN INTERRUPTED");
        assert_eq!(line, "Stopped by operator");
        assert_eq!(turn["execution"], "INTERRUPTED");
        assert_eq!(turn["outcome"], "NOT_ESTABLISHED");
        assert_eq!(model_summary, None);
        let with_summary = parse_event(r#"{"v":1,"type":"turn.result","turn_id":"t2","heading":"H","line":"L","turn":{},"model_summary":{"summary":"Fixed it.","notes":"n"}}"#).unwrap();
        assert!(matches!(
            with_summary,
            Event::TurnResult { model_summary: Some(ModelSummary { ref summary, ref notes }), .. }
                if summary == "Fixed it." && notes.as_deref() == Some("n")
        ));
    }

    #[test]
    fn lone_surrogate_escapes_become_replacement_characters() {
        let event = parse_event(
            r#"{"v":1,"type":"tool.end","turn_id":"t1","call_id":"c1","tool":"run_command","success":true,"summary":"ok \ud83d","lines":1}"#,
        );
        assert!(
            matches!(&event, Ok(Event::ToolEnd { summary, .. }) if summary == "ok \u{fffd}"),
            "{event:?}"
        );
        let event = parse_event(
            r#"{"v":1,"type":"assistant.delta","turn_id":"t1","text":"\ude00 \ud83d\ude00 \\ud83d \ud83d\u0041"}"#,
        );
        assert_eq!(
            event,
            Ok(Event::AssistantDelta {
                turn_id: "t1".into(),
                text: "\u{fffd} 😀 \\ud83d \u{fffd}A".into()
            })
        );
    }

    #[test]
    fn evidence_details_and_receipts_parse() {
        assert!(matches!(
            parse_event(r#"{"v":1,"type":"tool.start","turn_id":"t1","call_id":"c1","tool":"read_file","subject":"a.ts","evidence":"e4"}"#),
            Ok(Event::ToolStart { ref evidence, .. }) if evidence == "e4"
        ));
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"tool.detail","id":"d1","evidence":"e4","tool":"read_file","subject":"a.ts","status":"running","args":"{}","output":"","duration_ms":null}"#
            ),
            Ok(Event::ToolDetail {
                id: "d1".into(),
                status: "running".into(),
                args: "{}".into(),
                output: String::new(),
                duration_ms: None,
            })
        );
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"receipt","id":"r1","sections":[{"title":"Last turn","rows":[["outcome","VERIFIED"]]},{"title":"Validation receipt","rows":[],"note":"None yet."}]}"#
            ),
            Ok(Event::Receipt {
                id: "r1".into(),
                sections: vec![
                    ReceiptSection {
                        title: "Last turn".into(),
                        rows: vec![("outcome".into(), "VERIFIED".into())],
                        note: None,
                    },
                    ReceiptSection {
                        title: "Validation receipt".into(),
                        rows: Vec::new(),
                        note: Some("None yet.".into()),
                    },
                ],
            })
        );
    }

    #[test]
    fn unknown_event_types_are_tolerated() {
        assert_eq!(
            parse_event(r#"{"v":1,"type":"future.event","x":1}"#),
            Ok(Event::Unknown)
        );
    }

    #[test]
    fn hello_carries_the_catalogue_and_slash_results_and_notices_parse() {
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"hello","protocol":1,"pid":1,"commands":[{"name":"diff","usage":"/diff","summary":"Uncommitted changes as a diff"}]}"#
            ),
            Ok(Event::Hello {
                protocol: 1,
                commands: vec![SlashSpec {
                    name: "diff".into(),
                    usage: "/diff".into(),
                    summary: "Uncommitted changes as a diff".into()
                }]
            })
        );
        assert_eq!(
            parse_event(
                r#"{"v":1,"type":"slash.result","id":"s1","command":"diff","success":true,"output":"-a\n+b","format":"diff"}"#
            ),
            Ok(Event::SlashResult {
                id: "s1".into(),
                command: "diff".into(),
                success: true,
                output: "-a\n+b".into(),
                format: Some("diff".into()),
                composer: None,
                prompt: None,
            })
        );
        assert!(matches!(
            parse_event(r#"{"v":1,"type":"slash.result","id":"s2","command":"history","success":true,"output":"","prompt":"fix it"}"#),
            Ok(Event::SlashResult { prompt: Some(ref prompt), .. }) if prompt == "fix it"
        ));
        assert_eq!(
            parse_event(r#"{"v":1,"type":"notice","text":"Resumed session a (4 messages)."}"#),
            Ok(Event::Notice {
                text: "Resumed session a (4 messages).".into()
            })
        );
    }

    #[test]
    fn rejects_non_protocol_lines() {
        assert!(
            parse_event("Compiling harness")
                .unwrap_err()
                .contains("not JSON")
        );
        assert!(
            parse_event(r#"{"type":"hello","protocol":1}"#)
                .unwrap_err()
                .contains("unsupported protocol version")
        );
        assert!(
            parse_event(r#"{"v":2,"type":"hello","protocol":2}"#)
                .unwrap_err()
                .contains("unsupported protocol version")
        );
        assert!(
            parse_event(r#"{"v":1,"type":"tool.start","call_id":"c1"}"#)
                .unwrap_err()
                .contains("invalid event")
        );
    }

    #[test]
    fn commands_encode_as_single_versioned_lines() {
        for (command, expected) in [
            (
                Command::PromptSubmit {
                    id: "t1".into(),
                    text: "fix\nit".into(),
                },
                serde_json::json!({"v":1,"type":"prompt.submit","id":"t1","text":"fix\nit"}),
            ),
            (Command::Cancel, serde_json::json!({"v":1,"type":"cancel"})),
            (
                Command::Shutdown,
                serde_json::json!({"v":1,"type":"shutdown"}),
            ),
            (
                Command::Approve {
                    id: "approval-1".into(),
                    always: true,
                },
                serde_json::json!({"v":1,"type":"approve","id":"approval-1","always":true}),
            ),
            (
                Command::Deny {
                    id: "approval-1".into(),
                },
                serde_json::json!({"v":1,"type":"deny","id":"approval-1"}),
            ),
            (
                Command::Slash {
                    id: "s1".into(),
                    command: "diff".into(),
                    args: String::new(),
                },
                serde_json::json!({"v":1,"type":"slash","id":"s1","command":"diff","args":""}),
            ),
            (
                Command::ToolDetail {
                    id: "d1".into(),
                    evidence: "e4".into(),
                },
                serde_json::json!({"v":1,"type":"tool.detail","id":"d1","evidence":"e4"}),
            ),
            (
                Command::Receipt { id: "r1".into() },
                serde_json::json!({"v":1,"type":"receipt","id":"r1"}),
            ),
        ] {
            let line = encode_command(&command);
            assert!(line.ends_with('\n'));
            assert_eq!(
                line.matches('\n').count(),
                1,
                "embedded newlines must be escaped: {line:?}"
            );
            assert_eq!(serde_json::from_str::<Value>(&line).unwrap(), expected);
        }
    }

    #[test]
    fn approval_requests_carry_each_review_kind() {
        let review = |json: &str| match parse_event(&format!(
            r#"{{"v":1,"type":"approval.request","id":"a1","turn_id":"t1","tool":"t","subject":"s","preview":"{{}}","review":{json}}}"#
        )) {
            Ok(Event::ApprovalRequest { review, .. }) => review,
            other => panic!("{other:?}"),
        };
        assert_eq!(
            review(
                r#"{"kind":"change","path":"x.txt","before":null,"after":"hi\n","created":true,"truncated":false}"#
            ),
            Some(Review::Change {
                path: "x.txt".into(),
                before: None,
                after: "hi\n".into(),
                created: true,
                truncated: false
            })
        );
        assert_eq!(
            review(r#"{"kind":"patch","path":"a.ts","patch":"@@ -1 +1 @@","truncated":true}"#),
            Some(Review::Patch {
                path: "a.ts".into(),
                patch: "@@ -1 +1 @@".into(),
                truncated: true
            })
        );
        assert_eq!(
            review(r#"{"kind":"command","command":"npm test"}"#),
            Some(Review::Shell {
                command: "npm test".into()
            })
        );
        assert_eq!(
            review(r#"{"kind":"args","text":"{}","truncated":false}"#),
            Some(Review::Args {
                text: "{}".into(),
                truncated: false
            })
        );
        assert_eq!(review(r#"{"kind":"hologram"}"#), Some(Review::Unknown));
    }
}

//! `nexus-tui --live`: runs the agent sidecar and renders its protocol events in the terminal.
use std::{
    env,
    error::Error,
    io::{self, IsTerminal, Write},
    path::PathBuf,
    sync::{
        atomic::{AtomicBool, Ordering},
        mpsc,
    },
    time::Duration,
};

use crossterm::{
    event::{
        self, DisableBracketedPaste, EnableBracketedPaste, Event as TermEvent, KeyEventKind,
        KeyboardEnhancementFlags, PopKeyboardEnhancementFlags, PushKeyboardEnhancementFlags,
    },
    execute, terminal,
};

use crate::live_state::{Action, Link, LiveLayout, LiveState};
use crate::live_view::render_live;
use crate::sidecar::{Sidecar, SidecarMsg, SidecarSpec};

const SHUTDOWN_GRACE: Duration = Duration::from_secs(3);
const EXIT_GRACE: Duration = Duration::from_secs(2);
const INPUT_POLL: Duration = Duration::from_millis(30);
/// Must outlast the graceful shutdown (SHUTDOWN_GRACE plus the sidecar's group and stderr waits).
const STOP_WATCHDOG_GRACE: Duration = Duration::from_secs(6);

static STOP: AtomicBool = AtomicBool::new(false);
/// Set with STOP but never cleared, so the watchdog sees a stop even after the event loop consumed it.
static STOP_SIGNALLED: AtomicBool = AtomicBool::new(false);

#[cfg(unix)]
extern "C" fn request_stop(_signal: libc::c_int) {
    STOP.store(true, Ordering::SeqCst);
    STOP_SIGNALLED.store(true, Ordering::SeqCst);
}

/// SIGTERM and SIGHUP (terminal closed) end the session like `q`: the sidecar is shut down and the terminal
/// restored by the normal exit path.
#[cfg(unix)]
fn install_stop_signals() {
    for signal in [libc::SIGTERM, libc::SIGHUP] {
        // SAFETY: the handler only stores to an atomic, which is async-signal-safe.
        unsafe {
            libc::signal(signal, request_stop as *const () as libc::sighandler_t);
        }
    }
}

#[cfg(not(unix))]
fn install_stop_signals() {}

fn stop_requested() -> bool {
    STOP.swap(false, Ordering::SeqCst)
}

/// Exits the process when a stop signal has not ended the session within STOP_WATCHDOG_GRACE. crossterm's
/// input poll can spin forever on a hung-up terminal, so the event loop may never see the stop. Exiting closes
/// the sidecar's stdin, and the sidecar shuts itself down.
fn spawn_stop_watchdog() {
    std::thread::spawn(|| {
        while !STOP_SIGNALLED.load(Ordering::SeqCst) {
            std::thread::sleep(Duration::from_millis(50));
        }
        std::thread::sleep(STOP_WATCHDOG_GRACE);
        std::process::exit(1);
    });
}

pub const LIVE_USAGE: &str =
    "usage: nexus-tui --live [--sidecar PATH] [--node BIN] [-- SIDECAR_ARGS...]";

/// Runs `nexus-tui --live ARGS...`. A launch error is written to `stderr` as plain text. Returns the exit status.
pub fn main(args: Vec<String>, stderr: &mut dyn Write) -> i32 {
    match launch(args) {
        Ok(()) => 0,
        Err(err) => {
            let _ = writeln!(stderr, "nexus-tui: {err}");
            1
        }
    }
}

fn launch(args: Vec<String>) -> Result<(), Box<dyn Error>> {
    let spec = resolve_spec(
        args,
        env::var("NEXUS_SIDECAR").ok(),
        env::var("NEXUS_NODE").ok(),
        env::current_exe().ok(),
    )?;
    if !io::stdin().is_terminal() || !io::stdout().is_terminal() {
        return Err("interactive Nexus TUI requires a terminal".into());
    }
    run_live(spec)
}

/// Resolves the sidecar command line. Precedence: flags, then `NEXUS_SIDECAR` / `NEXUS_NODE`, then the
/// `cli/dist/sidecar.js` of the checkout whose `core/target/<profile>/` holds this binary.
pub fn resolve_spec(
    args: Vec<String>,
    env_sidecar: Option<String>,
    env_node: Option<String>,
    exe: Option<PathBuf>,
) -> Result<SidecarSpec, String> {
    let mut sidecar = env_sidecar.map(PathBuf::from);
    let mut node = env_node.unwrap_or_else(|| "node".to_string());
    let mut passthrough = Vec::new();
    let mut args = args.into_iter();
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--sidecar" => sidecar = Some(PathBuf::from(args.next().ok_or(LIVE_USAGE)?)),
            "--node" => node = args.next().ok_or(LIVE_USAGE)?,
            "--" => {
                passthrough.extend(args.by_ref());
                break;
            }
            other => return Err(format!("unknown option {other}\n{LIVE_USAGE}")),
        }
    }
    let sidecar = sidecar
        .or_else(|| {
            exe.and_then(|exe| {
                exe.ancestors()
                    .nth(4)
                    .map(|root| root.join("cli/dist/sidecar.js"))
            })
        })
        .ok_or("cannot locate cli/dist/sidecar.js; pass --sidecar PATH")?;
    if !sidecar.is_file() {
        return Err(format!(
            "sidecar not found at {}; run `make build` or pass --sidecar PATH",
            sidecar.display()
        ));
    }
    let mut spec_args = vec![sidecar.display().to_string()];
    spec_args.extend(passthrough);
    Ok(SidecarSpec {
        program: node,
        args: spec_args,
    })
}

/// The live session without the terminal: sidecar lifecycle plus state. The event loop feeds it keys.
pub struct LiveApp {
    pub state: LiveState,
    spec: SidecarSpec,
    sidecar: Option<Sidecar>,
    messages: mpsc::Receiver<SidecarMsg>,
}

impl LiveApp {
    pub fn start(spec: SidecarSpec) -> LiveApp {
        let (_, messages) = mpsc::channel();
        let mut app = LiveApp {
            state: LiveState::new(),
            spec,
            sidecar: None,
            messages,
        };
        app.spawn();
        app
    }

    fn spawn(&mut self) {
        let (sender, messages) = mpsc::channel();
        self.messages = messages;
        match Sidecar::spawn(&self.spec, sender) {
            Ok(sidecar) => self.sidecar = Some(sidecar),
            Err(err) => self.state.fail(
                format!(
                    "Could not start the agent sidecar with {}: {err}",
                    self.spec.program
                ),
                None,
                Vec::new(),
            ),
        }
    }

    /// Applies every pending sidecar message. Returns true when the screen needs a redraw.
    pub fn pump(&mut self) -> bool {
        let mut changed = false;
        while self.sidecar.is_some() {
            let Ok(message) = self.messages.try_recv() else {
                break;
            };
            changed = true;
            match message {
                SidecarMsg::Event(event) => {
                    self.state.apply(event);
                    for action in self.state.take_outbox() {
                        self.handle(action);
                    }
                    if matches!(self.state.link, Link::Crashed { .. })
                        && let Some(mut sidecar) = self.sidecar.take()
                    {
                        sidecar.reap(Duration::ZERO);
                    }
                }
                SidecarMsg::Malformed => self.stop(
                    "The agent sidecar wrote output that is not part of the protocol.",
                    Duration::ZERO,
                ),
                SidecarMsg::Closed => {
                    self.stop("The agent sidecar exited unexpectedly.", EXIT_GRACE)
                }
            }
        }
        changed
    }

    fn stop(&mut self, reason: &str, grace: Duration) {
        if let Some(mut sidecar) = self.sidecar.take() {
            let code = sidecar.reap(grace);
            self.state
                .fail(reason.to_string(), code, sidecar.stderr_tail());
        }
    }

    /// Carries out an operator action. Returns false when the app should exit.
    pub fn handle(&mut self, action: Action) -> bool {
        match action {
            Action::Send(command) => {
                if let Some(sidecar) = self.sidecar.as_mut() {
                    // A failed write means the child is gone; its Closed message reports that.
                    let _ = sidecar.send(&command);
                }
                true
            }
            Action::Quit => {
                if let Some(sidecar) = self.sidecar.take() {
                    sidecar.shutdown(SHUTDOWN_GRACE);
                }
                false
            }
            Action::Restart => {
                if let Some(mut sidecar) = self.sidecar.take() {
                    sidecar.reap(Duration::ZERO);
                }
                self.state.restarted();
                self.spawn();
                true
            }
        }
    }
}

/// Restores the terminal on every exit path. ratatui's panic hook restores raw mode and the alternate screen
/// but not bracketed paste or the keyboard protocol, so those are undone here, during unwinding as well.
struct TerminalGuard {
    keyboard_protocol: bool,
}

impl Drop for TerminalGuard {
    fn drop(&mut self) {
        if self.keyboard_protocol {
            let _ = execute!(io::stdout(), PopKeyboardEnhancementFlags);
        }
        let _ = execute!(io::stdout(), DisableBracketedPaste);
        ratatui::restore();
    }
}

pub fn run_live(spec: SidecarSpec) -> Result<(), Box<dyn std::error::Error>> {
    install_stop_signals();
    spawn_stop_watchdog();
    let mut guard = TerminalGuard {
        keyboard_protocol: false,
    };
    let mut terminal = ratatui::try_init()?;
    execute!(io::stdout(), EnableBracketedPaste)?;
    // Lets Shift+Enter arrive as its own key on terminals that speak the kitty keyboard protocol.
    if terminal::supports_keyboard_enhancement().unwrap_or(false) {
        execute!(
            io::stdout(),
            PushKeyboardEnhancementFlags(KeyboardEnhancementFlags::DISAMBIGUATE_ESCAPE_CODES)
        )?;
        guard.keyboard_protocol = true;
    }
    let mut app = LiveApp::start(spec);
    let result = event_loop(&mut terminal, &mut app);
    app.handle(Action::Quit);
    result
}

fn draw(terminal: &mut ratatui::DefaultTerminal, app: &mut LiveApp) -> io::Result<()> {
    let mut layout = LiveLayout::default();
    terminal.draw(|frame| layout = render_live(frame, &app.state))?;
    app.state.note_layout(layout);
    Ok(())
}

fn event_loop(
    terminal: &mut ratatui::DefaultTerminal,
    app: &mut LiveApp,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut redraw = true;
    loop {
        if stop_requested() {
            app.state.closing = true;
            draw(terminal, app)?;
            return Ok(());
        }
        redraw |= app.pump();
        if redraw {
            draw(terminal, app)?;
            redraw = false;
        }
        if !event::poll(INPUT_POLL)? {
            continue;
        }
        let action = match event::read()? {
            TermEvent::Key(key) if key.kind == KeyEventKind::Press => app.state.on_key(key),
            TermEvent::Paste(text) => {
                app.state.on_paste(&text);
                None
            }
            TermEvent::Resize(_, _) => None,
            _ => continue,
        };
        redraw = true;
        let Some(action) = action else {
            continue;
        };
        if action == Action::Quit {
            app.state.closing = true;
            draw(terminal, app)?;
        }
        if !app.handle(action) {
            return Ok(());
        }
    }
}

