export function seedRequirements(objective: string): Array<{ id: string; text: string }> {
  const lines = objective.replace(/\r\n?/g, "\n").split("\n");
  const items: Array<{ indent: number; text: string }> = [];
  for (const line of lines) {
    const match = /^(\s*)(?:R?(\d{1,3})[.):]|R(\d{1,3})\s*[-–—])\s+(\S.*)$/.exec(line);
    if (!match) continue;
    items.push({ indent: match[1].replace(/\t/g, "    ").length, text: match[4].trim() });
