321	    frame.render_widget(
322	        Paragraph::new(Line::from(vec![
323	            Span::styled(
324	                tool_verb(&approval.tool),
325	                Style::default()
326	                    .fg(Color::White)
327	                    .add_modifier(Modifier::BOLD),
328	            ),
329	            Span::styled(format!(" {}", approval.subject), Style::default().fg(MUTED)),
330	        ])),
331	        head,
332	    );
333	    let rows = usize::from(body.height);
334	    let limit = approval.lines.len().saturating_sub(rows);
335	    let lines: Vec<Line> = approval
