363	/// How a row of a command's `diff` output is coloured: rows that are not part of a hunk read as headers.
364	fn diff_row_kind(row: &str) -> LineKind {
365	    if row.starts_with('+') && !row.starts_with("+++") {
366	        LineKind::Added
367	    } else if row.starts_with('-') && !row.starts_with("---") {
368	        LineKind::Removed
369	    } else if row.starts_with("@@") {
370	        LineKind::Hunk
371	    } else if row.starts_with(' ') {
372	        LineKind::Context
373	    } else {
374	        LineKind::Meta
375	    }
376	}
