380	/// Slash-command completion: up to six rows at the bottom of the transcript area, the highlighted one in accent.
381	fn render_completion(frame: &mut Frame, area: Rect, found: &[&SlashSpec], pick: usize) {
382	    let shown = found
383	        .len()
384	        .min(MAX_COMPLETION_ROWS)
385	        .min(usize::from(area.height));
386	    if shown == 0 {
387	        return;
388	    }
389	    let first = (pick + 1).saturating_sub(shown);
390	    let width = found
391	        .iter()
392	        .map(|spec| spec.usage.chars().count())
393	        .max()
394	        .unwrap_or(0)
395	        .min(40);
396	    let lines: Vec<Line> = found
397	        .iter()
398	        .enumerate()
399	        .skip(first)
400	        .take(shown)
401	        .map(|(index, spec)| {
402	            let style = if index == pick {
403	                Style::default().fg(Color::Black).bg(ACCENT)
404	            } else {
405	                Style::default().fg(Color::White).bg(SURFACE)
406	            };
407	            Line::from(Span::styled(
408	                format!(" {:<width$}  {} ", spec.usage, spec.summary),
409	                style,
410	            ))
411	        })
412	        .collect();
413	    let height = u16::try_from(shown).unwrap_or(0);
414	    let rect = Rect::new(area.x, area.bottom() - height, area.width, height);
415	    frame.render_widget(Clear, rect);
416	    frame.render_widget(
417	        Paragraph::new(lines).style(Style::default().bg(SURFACE)),
418	        rect,
419	    );
420	}
