488	/// Renders wrapped `lines` from wrapped row `scroll`; returns the visible rows and the largest useful scroll.
489	fn scroll_body(
490	    frame: &mut Frame,
491	    area: Rect,
492	    lines: Vec<Line<'_>>,
493	    scroll: usize,
