780	/// Renders the transcript window `scroll_back` rows above the newest line, with `selected` highlighted. With
781	/// `follow`, the window first moves the least distance that shows the whole selected entry above the bottom row
782	/// (its top when it is taller than the window). Only the entries needed to fill the window are laid out, so the cost follows the
783	/// window, not the transcript. Returns the largest useful `scroll_back` (`usize::MAX` when the walk stopped
784	/// before the first entry) and the `scroll_back` drawn.
785	fn render_transcript(
786	    frame: &mut Frame,
787	    area: Rect,
788	    transcript: &[Entry],
789	    scroll_back: usize,
790	    selected: Option<usize>,
791	    follow: bool,
792	) -> (usize, usize) {
793	    let height = usize::from(area.height);
794	    let mut back = scroll_back;
795	    let mut target = selected.filter(|_| follow);
796	    let mut tail = Vec::new();
797	    let mut total: usize = 0;
798	    let mut reached_top = true;
799	    'entries: for (index, entry) in transcript.iter().enumerate().rev() {
800	        let below = total;
801	        let highlight = selected == Some(index);
802	        for line in entry_lines(entry, index == 0).into_iter().rev() {
803	            let line = if highlight {
804	                line.patch_style(Style::default().bg(SELECTED).add_modifier(Modifier::BOLD))
805	            } else {
806	                line
807	            };
808	            let rows = wrapped_rows(&line, area.width);
809	            total = total.saturating_add(rows);
810	            tail.push((line, rows));
811	            if target.is_none() && total >= height.saturating_add(back) {
812	                reached_top = false;
813	                break 'entries;
814	            }
815	        }
816	        if target == Some(index) {
817	            // One row short of the bottom, where the scroll badge would cover the entry.
818	            back = back
819	                .min(below.saturating_sub(1))
820	                .max(total.saturating_sub(height));
821	            target = None;
822	            if total >= height.saturating_add(back) {
823	                reached_top = false;
824	                break;
825	            }
826	        }
827	    }
828	    let limit = if reached_top {
829	        total.saturating_sub(height)
830	    } else {
831	        usize::MAX
832	    };
833	    let back = back.min(limit);
834	    let first_row = total.saturating_sub(height.saturating_add(back));
835	    tail.reverse();
836	    let mut skipped = 0;
837	    let mut covered = 0;
838	    let mut lines = Vec::new();
839	    for (line, rows) in tail {
840	        if lines.is_empty() && skipped + rows <= first_row {
841	            skipped += rows;
842	            continue;
843	        }
844	        if covered >= height + (first_row - skipped) {
845	            break;
846	        }
847	        covered += rows;
848	        lines.push(line);
849	    }
850	    let offset = u16::try_from(first_row - skipped).unwrap_or(u16::MAX);
851	    frame.render_widget(
852	        Paragraph::new(lines)
853	            .wrap(Wrap { trim: false })
854	            .scroll((offset, 0)),
855	        area,
856	    );
857	    if back > 0 {
858	        render_scroll_badge(frame, area, back);
859	    }
860	    (limit, back)
861	}
