1137	fn render_crash(frame: &mut Frame, area: Rect, code: Option<i32>, reason: &str, stderr: &[String]) {
1138	    let muted = Style::default().fg(MUTED);
1139	    let key = Style::default().fg(ACCENT).add_modifier(Modifier::BOLD);
1140	    let exit = code.map_or_else(
1141	        || "no exit code".to_string(),
1142	        |code| format!("exit code {code}"),
1143	    );
1144	    let rows = |line: &Line<'_>| wrapped_rows(line, area.width);
1145	    let heading = Line::from(Span::styled(
1146	        "× The agent sidecar stopped",
1147	        Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
1148	    ));
1149	    let detail = Line::from(Span::styled(
1150	        format!("{} ({exit})", one_line(reason)),
1151	        Style::default().fg(Color::White),
1152	    ));
1153	    let recovery = [
1154	        Line::from(vec![
1155	            Span::styled("r", key),
1156	            Span::raw(" restart   "),
1157	            Span::styled("q", key),
1158	            Span::raw(" quit"),
1159	        ]),
1160	        Line::from(Span::styled(
1161	            "A restarted agent does not remember this conversation.",
1162	            muted,
1163	        )),
1164	    ];
1165	    // Priority when rows are short: reason and exit code, recovery keys, heading, spacing, then stderr.
1166	    let mut room = usize::from(area.height)
1167	        .saturating_sub(rows(&detail) + recovery.iter().map(&rows).sum::<usize>());
1168	    let mut lines = Vec::new();
1169	    if room > 0 {
1170	        lines.push(heading);
1171	        room -= 1;
1172	    }
1173	    lines.push(detail);
1174	    let gap = room > 0;
1175	    if gap {
1176	        room -= 1;
1177	    }
1178	    let label = Line::from(Span::styled(
1179	        "Last diagnostic lines (secrets redacted):",
1180	        muted,
1181	    ));
1182	    let overhead = 1 + rows(&label);
1183	    if room > overhead {
1184	        room -= overhead;
1185	        let mut tail = Vec::new();
1186	        for row in stderr.iter().rev() {
1187	            let line = Line::from(Span::styled(format!("  {row}"), muted));
1188	            let need = rows(&line);
1189	            if need > room {
1190	                break;
1191	            }
1192	            room -= need;
1193	            tail.push(line);
1194	        }
1195	        if !tail.is_empty() {
1196	            lines.push(Line::default());
1197	            lines.push(label);
1198	            lines.extend(tail.into_iter().rev());
1199	        }
1200	    }
1201	    if gap {
1202	        lines.push(Line::default());
1203	    }
1204	    lines.extend(recovery);
1205	    frame.render_widget(Paragraph::new(lines).wrap(Wrap { trim: false }), area);
