        KeyCode::Down | KeyCode::Char('j') => {
            self.scroll_back = self.scroll_back.saturating_sub(1)
        }
        KeyCode::Home | KeyCode::Char('g') => self.scroll_back = usize::MAX,
        KeyCode::End | KeyCode::Char('G') => self.scroll_back = 0,
        KeyCode::Enter => {
