//! Colour depth and theme tokens for the live TUI. The views draw with 24-bit colours; on a terminal that cannot show
//! them, `downsample` maps every cell of the finished frame to the nearest colour the terminal has (256 or 16), or
//! removes colour entirely (`NO_COLOR`, `TERM=dumb`), keeping bold/reverse so selection and emphasis survive.
use ratatui::{
    buffer::Buffer,
    style::{Color, Modifier},
};

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Depth {
    #[default]
    TrueColor,
    Ansi256,
    Ansi16,
    Mono,
}

impl Depth {
    /// From the environment: `NEXUS_COLOR` (truecolor, 256, 16, none) overrides; a non-empty `NO_COLOR` or
    /// `TERM=dumb` means no colour; `COLORTERM=truecolor|24bit` means 24-bit; a `TERM` naming 256 colours means 256;
    /// anything else is assumed to have the 16 standard colours.
    pub fn detect(var: impl Fn(&str) -> Option<String>) -> Depth {
        let get = |name: &str| var(name).filter(|value| !value.is_empty());
        if let Some(choice) = get("NEXUS_COLOR") {
            match choice.to_ascii_lowercase().as_str() {
                "truecolor" | "24bit" | "24" => return Depth::TrueColor,
                "256" => return Depth::Ansi256,
                "16" | "ansi" => return Depth::Ansi16,
                "none" | "mono" | "0" | "off" => return Depth::Mono,
                _ => {}
            }
        }
        if get("NO_COLOR").is_some() {
            return Depth::Mono;
        }
        let term = get("TERM").unwrap_or_default();
        if term == "dumb" {
            return Depth::Mono;
        }
        if matches!(get("COLORTERM").as_deref(), Some("truecolor" | "24bit")) {
            return Depth::TrueColor;
        }
        if term.contains("256color") {
            return Depth::Ansi256;
        }
        Depth::Ansi16
    }

    pub fn from_env() -> Depth {
        Depth::detect(|name| std::env::var(name).ok())
    }
}

/// Maps the colours of every cell to what `depth` can show. A no-op for 24-bit terminals.
pub fn downsample(buffer: &mut Buffer, depth: Depth) {
    if depth == Depth::TrueColor {
        return;
    }
    for cell in buffer.content.iter_mut() {
        if depth == Depth::Mono {
            // A background carried meaning (selection, the status bar, a badge): reverse video keeps it visible.
            if !matches!(cell.bg, Color::Reset) {
                cell.modifier.insert(Modifier::REVERSED);
            }
            cell.fg = Color::Reset;
            cell.bg = Color::Reset;
            continue;
        }
        cell.fg = reduce(cell.fg, depth);
        cell.bg = reduce(cell.bg, depth);
    }
}

fn reduce(color: Color, depth: Depth) -> Color {
    match (color, depth) {
        (Color::Rgb(r, g, b), Depth::Ansi256) => Color::Indexed(nearest_256(r, g, b)),
        (Color::Rgb(r, g, b), Depth::Ansi16) => nearest_16(r, g, b),
        (Color::Indexed(index), Depth::Ansi16) if index >= 16 => {
            let (r, g, b) = rgb_of_256(index);
            nearest_16(r, g, b)
        }
        _ => color,
    }
}

const CUBE: [u8; 6] = [0, 95, 135, 175, 215, 255];

fn distance(a: (u8, u8, u8), b: (u8, u8, u8)) -> u32 {
    let d = |x: u8, y: u8| (i32::from(x) - i32::from(y)).pow(2) as u32;
    d(a.0, b.0) + d(a.1, b.1) + d(a.2, b.2)
}

/// The xterm 256-colour palette entry (16–255) nearest to an RGB colour.
pub fn nearest_256(r: u8, g: u8, b: u8) -> u8 {
    let level = |v: u8| {
        CUBE.iter()
            .enumerate()
            .min_by_key(|(_, c)| (i32::from(**c) - i32::from(v)).abs())
            .map(|(i, _)| i as u8)
            .unwrap_or(0)
    };
    let (ri, gi, bi) = (level(r), level(g), level(b));
    let cube = 16 + 36 * ri + 6 * gi + bi;
    let cube_rgb = (CUBE[ri as usize], CUBE[gi as usize], CUBE[bi as usize]);
    let average = (u32::from(r) + u32::from(g) + u32::from(b)) / 3;
    let gray_index = (average.saturating_sub(8) / 10).min(23) as u8;
    let gray_value = 8 + 10 * gray_index;
    let gray = 232 + gray_index;
    if distance((r, g, b), (gray_value, gray_value, gray_value)) < distance((r, g, b), cube_rgb) {
        gray
    } else {
        cube
    }
}

fn rgb_of_256(index: u8) -> (u8, u8, u8) {
    match index {
        16..=231 => {
            let i = index - 16;
            (CUBE[(i / 36) as usize], CUBE[((i / 6) % 6) as usize], CUBE[(i % 6) as usize])
        }
        232..=255 => {
            let v = 8 + 10 * (index - 232);
            (v, v, v)
        }
        _ => (128, 128, 128),
    }
}

/// The standard 16-colour entry nearest to an RGB colour (xterm's default values).
fn nearest_16(r: u8, g: u8, b: u8) -> Color {
    const TABLE: [((u8, u8, u8), Color); 16] = [
        ((0, 0, 0), Color::Black),
        ((205, 0, 0), Color::Red),
        ((0, 205, 0), Color::Green),
        ((205, 205, 0), Color::Yellow),
        ((0, 0, 238), Color::Blue),
        ((205, 0, 205), Color::Magenta),
        ((0, 205, 205), Color::Cyan),
        ((229, 229, 229), Color::Gray),
        ((127, 127, 127), Color::DarkGray),
        ((255, 0, 0), Color::LightRed),
        ((0, 255, 0), Color::LightGreen),
        ((255, 255, 0), Color::LightYellow),
        ((92, 92, 255), Color::LightBlue),
        ((255, 0, 255), Color::LightMagenta),
        ((0, 255, 255), Color::LightCyan),
        ((255, 255, 255), Color::White),
    ];
    TABLE
        .iter()
        .min_by_key(|(rgb, _)| distance(*rgb, (r, g, b)))
        .map(|(_, color)| *color)
        .unwrap_or(Color::Reset)
}

/// WCAG relative luminance of an sRGB colour.
pub fn luminance((r, g, b): (u8, u8, u8)) -> f64 {
    let channel = |v: u8| {
        let c = f64::from(v) / 255.0;
        if c <= 0.039_28 { c / 12.92 } else { ((c + 0.055) / 1.055).powf(2.4) }
    };
    0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b)
}

/// WCAG contrast ratio between two colours (1.0 to 21.0).
pub fn contrast(a: (u8, u8, u8), b: (u8, u8, u8)) -> f64 {
    let (x, y) = (luminance(a), luminance(b));
    let (hi, lo) = if x > y { (x, y) } else { (y, x) };
    (hi + 0.05) / (lo + 0.05)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn env(pairs: &[(&str, &str)]) -> impl Fn(&str) -> Option<String> {
        let owned: Vec<(String, String)> = pairs.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect();
        move |name| owned.iter().find(|(k, _)| k == name).map(|(_, v)| v.clone())
    }

    #[test]
    fn colour_depth_follows_the_environment_with_an_explicit_override() {
        assert_eq!(Depth::detect(env(&[("COLORTERM", "truecolor"), ("TERM", "xterm")])), Depth::TrueColor);
        assert_eq!(Depth::detect(env(&[("TERM", "xterm-256color")])), Depth::Ansi256);
        assert_eq!(Depth::detect(env(&[("TERM", "xterm")])), Depth::Ansi16);
        assert_eq!(Depth::detect(env(&[("TERM", "dumb"), ("COLORTERM", "truecolor")])), Depth::Mono);
        assert_eq!(Depth::detect(env(&[("NO_COLOR", "1"), ("COLORTERM", "truecolor")])), Depth::Mono);
        assert_eq!(Depth::detect(env(&[("NO_COLOR", ""), ("COLORTERM", "truecolor")])), Depth::TrueColor, "an empty NO_COLOR is unset");
        assert_eq!(Depth::detect(env(&[("NEXUS_COLOR", "16"), ("COLORTERM", "truecolor")])), Depth::Ansi16);
        assert_eq!(Depth::detect(env(&[("NEXUS_COLOR", "none")])), Depth::Mono);
    }

    #[test]
    fn downsampling_maps_to_the_nearest_palette_entry_and_mono_keeps_backgrounds_as_reverse_video() {
        assert_eq!(nearest_256(0, 95, 0), 22);
        assert_eq!(nearest_256(255, 255, 255), 231);
        assert_eq!(nearest_256(18, 18, 18), 233);
        assert_eq!(nearest_16(200, 10, 10), Color::Red);
        let mut buffer = Buffer::empty(ratatui::layout::Rect::new(0, 0, 2, 1));
        buffer.content[0].set_fg(Color::Rgb(0, 200, 0)).set_bg(Color::Rgb(20, 20, 20));
        let mut mono = buffer.clone();
        downsample(&mut buffer, Depth::Ansi16);
        assert_eq!((buffer.content[0].fg, buffer.content[0].bg), (Color::Green, Color::Black));
        downsample(&mut mono, Depth::Mono);
        assert_eq!((mono.content[0].fg, mono.content[0].bg), (Color::Reset, Color::Reset));
        assert!(mono.content[0].modifier.contains(Modifier::REVERSED));
        assert!(!mono.content[1].modifier.contains(Modifier::REVERSED), "cells without a background stay plain");
    }

    #[test]
    fn contrast_matches_the_wcag_reference_values() {
        assert!((contrast((0, 0, 0), (255, 255, 255)) - 21.0).abs() < 0.01);
        assert!((contrast((119, 119, 119), (255, 255, 255)) - 4.48).abs() < 0.02);
    }
}

//! A small lexical highlighter for diff rows: keywords, strings, comments, numbers and type-like names for common
//! languages, chosen by file extension. It is line-based on purpose — a diff shows fragments of a file, so nothing
//! outside the line is known. A block comment or string that spans lines is coloured on the line that opens it, and
//! continuation lines that start with `*` (the usual doc-comment style) are coloured as comment. Anything it does not
//! recognise stays plain text, so a wrong guess costs colour, never content.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Token {
    Plain,
    Keyword,
    Str,
    Comment,
    Number,
    Type,
}

pub struct Lang {
    line_comments: &'static [&'static str],
    block_comment: Option<(&'static str, &'static str)>,
    quotes: &'static [char],
    keywords: &'static [&'static str],
    /// Capitalised identifiers read as type names.
    types: bool,
    /// `'` opens a string only around one character (`'a'`, `'\n'`), so Rust lifetimes stay plain.
    strict_single_quote: bool,
}

const C_LIKE_COMMENT: Option<(&str, &str)> = Some(("/*", "*/"));

static RUST: Lang = Lang {
    line_comments: &["//"],
    block_comment: C_LIKE_COMMENT,
    quotes: &['"', '\''],
    keywords: &[
        "as", "async", "await", "break", "const", "continue", "crate", "dyn", "else", "enum", "extern", "false", "fn",
        "for", "if", "impl", "in", "let", "loop", "match", "mod", "move", "mut", "pub", "ref", "return", "self", "Self",
        "static", "struct", "super", "trait", "true", "type", "unsafe", "use", "where", "while",
    ],
    types: true,
    strict_single_quote: true,
};

static TYPESCRIPT: Lang = Lang {
    line_comments: &["//"],
    block_comment: C_LIKE_COMMENT,
    quotes: &['"', '\'', '`'],
    keywords: &[
        "abstract", "as", "async", "await", "break", "case", "catch", "class", "const", "continue", "debugger",
        "declare", "default", "delete", "do", "else", "enum", "export", "extends", "false", "finally", "for", "from",
        "function", "get", "if", "implements", "import", "in", "instanceof", "interface", "let", "new", "null", "of",
        "private", "protected", "public", "readonly", "return", "set", "static", "super", "switch", "this", "throw",
        "true", "try", "type", "typeof", "undefined", "var", "void", "while", "yield",
    ],
    types: true,
    strict_single_quote: false,
};

static PYTHON: Lang = Lang {
    line_comments: &["#"],
    block_comment: None,
    quotes: &['"', '\''],
    keywords: &[
        "False", "None", "True", "and", "as", "assert", "async", "await", "break", "class", "continue", "def", "del",
        "elif", "else", "except", "finally", "for", "from", "global", "if", "import", "in", "is", "lambda", "match",
        "nonlocal", "not", "or", "pass", "raise", "return", "self", "try", "while", "with", "yield",
    ],
    types: true,
    strict_single_quote: false,
};

static GO: Lang = Lang {
    line_comments: &["//"],
    block_comment: C_LIKE_COMMENT,
    quotes: &['"', '`', '\''],
    keywords: &[
        "break", "case", "chan", "const", "continue", "default", "defer", "else", "fallthrough", "false", "for", "func",
        "go", "goto", "if", "import", "interface", "map", "nil", "package", "range", "return", "select", "struct",
        "switch", "true", "type", "var",
    ],
    types: true,
    strict_single_quote: false,
};

static SHELL: Lang = Lang {
    line_comments: &["#"],
    block_comment: None,
    quotes: &['"', '\''],
    keywords: &[
        "case", "do", "done", "elif", "else", "esac", "exit", "export", "fi", "for", "function", "if", "in", "local",
        "readonly", "return", "set", "then", "until", "while",
    ],
    types: false,
    strict_single_quote: false,
};

static C_FAMILY: Lang = Lang {
    line_comments: &["//"],
    block_comment: C_LIKE_COMMENT,
    quotes: &['"', '\''],
    keywords: &[
        "auto", "bool", "break", "case", "char", "class", "const", "continue", "default", "do", "double", "else",
        "enum", "extends", "extern", "false", "final", "float", "for", "fun", "if", "implements", "import", "int",
        "interface", "long", "namespace", "new", "null", "nullptr", "package", "private", "protected", "public",
        "return", "short", "signed", "sizeof", "static", "struct", "switch", "template", "this", "throw", "true",
        "try", "typedef", "union", "unsigned", "using", "val", "var", "virtual", "void", "volatile", "while",
    ],
    types: true,
    strict_single_quote: false,
};

static DATA: Lang = Lang {
    line_comments: &["#"],
    block_comment: None,
    quotes: &['"', '\''],
    keywords: &["true", "false", "null", "yes", "no", "on", "off"],
    types: false,
    strict_single_quote: false,
};

static JSON: Lang = Lang {
    line_comments: &[],
    block_comment: None,
    quotes: &['"'],
    keywords: &["true", "false", "null"],
    types: false,
    strict_single_quote: false,
};

/// The language for a path, by extension; `None` leaves the content plain.
pub fn lang_for(path: &str) -> Option<&'static Lang> {
    let name = path.rsplit('/').next().unwrap_or(path);
    if matches!(name, "Makefile" | "Dockerfile" | ".bashrc" | ".zshrc" | ".profile") {
        return Some(&SHELL);
    }
    let ext = name.rsplit_once('.').map(|(_, ext)| ext.to_ascii_lowercase())?;
    Some(match ext.as_str() {
        "rs" => &RUST,
        "ts" | "tsx" | "js" | "jsx" | "mjs" | "cjs" | "mts" | "cts" => &TYPESCRIPT,
        "py" | "pyi" => &PYTHON,
        "go" => &GO,
        "sh" | "bash" | "zsh" => &SHELL,
        "c" | "h" | "cc" | "cpp" | "cxx" | "hpp" | "java" | "kt" | "kts" | "cs" | "swift" => &C_FAMILY,
        "toml" | "yaml" | "yml" | "ini" | "cfg" | "conf" | "env" => &DATA,
        "json" | "jsonc" => &JSON,
        _ => return None,
    })
}

fn ident_start(c: char) -> bool {
    c.is_alphabetic() || c == '_' || c == '$'
}

fn ident_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || c == '$'
}

/// Byte ranges of `text` with their token class, covering the whole line in order.
pub fn highlight(lang: &Lang, text: &str) -> Vec<(usize, usize, Token)> {
    let mut out: Vec<(usize, usize, Token)> = Vec::new();
    let mut push = |start: usize, end: usize, token: Token| {
        if start >= end {
            return;
        }
        match out.last_mut() {
            Some(last) if last.2 == token && last.1 == start => last.1 = end,
            _ => out.push((start, end, token)),
        }
    };
    let trimmed = text.trim_start();
    if lang.block_comment.is_some() && (trimmed.starts_with("* ") || trimmed == "*" || trimmed.starts_with("*/")) {
        push(0, text.len(), Token::Comment);
        return out;
    }
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    let at = |i: usize| chars.get(i).map(|(_, c)| *c);
    let byte = |i: usize| chars.get(i).map_or(text.len(), |(b, _)| *b);
    let mut i = 0;
    while i < chars.len() {
        let start = byte(i);
        let rest = &text[start..];
        if let Some(prefix) = lang.line_comments.iter().find(|p| rest.starts_with(**p)) {
            // `#` is a comment only at a word boundary (so `$#` or `a#b` stay plain in shell and data files).
            let boundary = *prefix != "#" || i == 0 || at(i - 1).is_some_and(char::is_whitespace);
            if boundary {
                push(start, text.len(), Token::Comment);
                return out;
            }
        }
        if let Some((open, close)) = lang.block_comment
            && rest.starts_with(open)
        {
            let end = rest[open.len()..].find(close).map_or(text.len(), |at| start + open.len() + at + close.len());
            push(start, end, Token::Comment);
            while i < chars.len() && byte(i) < end {
                i += 1;
            }
            continue;
        }
        let c = chars[i].1;
        if lang.quotes.contains(&c) {
            if c == '\'' && lang.strict_single_quote {
                let char_literal = match (at(i + 1), at(i + 2), at(i + 3)) {
                    (Some('\\'), Some(_), _) => true,
                    (Some(x), Some('\''), _) if x != '\'' => true,
                    _ => false,
                };
                if !char_literal {
                    push(start, byte(i + 1), Token::Plain);
                    i += 1;
                    continue;
                }
            }
            let mut j = i + 1;
            while j < chars.len() {
                match chars[j].1 {
                    '\\' => j += 2,
                    q if q == c => {
                        j += 1;
                        break;
                    }
                    _ => j += 1,
                }
            }
            let end = byte(j.min(chars.len()));
            push(start, end, Token::Str);
            i = j.min(chars.len());
            continue;
        }
        if c.is_ascii_digit() && !(i > 0 && at(i - 1).is_some_and(ident_char)) {
            let mut j = i + 1;
            while j < chars.len() && (chars[j].1.is_ascii_alphanumeric() || chars[j].1 == '_' || chars[j].1 == '.') {
                j += 1;
            }
            push(start, byte(j), Token::Number);
            i = j;
            continue;
        }
        if ident_start(c) {
            let mut j = i + 1;
            while j < chars.len() && ident_char(chars[j].1) {
                j += 1;
            }
            let word = &text[start..byte(j)];
            let token = if lang.keywords.contains(&word) {
                Token::Keyword
            } else if lang.types && c.is_uppercase() && word.chars().any(char::is_lowercase) {
                Token::Type
            } else {
                Token::Plain
            };
            push(start, byte(j), token);
            i = j;
            continue;
        }
        push(start, byte(i + 1), Token::Plain);
        i += 1;
    }
    out
}

