    #[test]
    fn a_card_bounds_its_preview_and_counts_exactly_what_it_omits() {
        let mut text = String::from("--- a/f.txt\n+++ b/f.txt\n@@ -1,20 +1,20 @@\n");
        for i in 1..=20 {
