                }
                lines.extend(row_lines(*row));
            }
            lines.truncate(height);
            if content.rows.is_empty() {
                lines.push(Line::from(Span::styled("The diff has no line changes.", muted)));
            }
            let shown_last = (top + lines.len()).min(content.rows.len());
            block = block.title(
