        assert!(added.ends_with("›│"), "clipped content is marked: {added:?}");
        for _ in 0..40 {
            state.on_key(key(KeyCode::Right));
        }
        let rows = screen(&draw(&mut state, 60, 16));
        let added = rows.iter().find(|r| r.contains('‹')).unwrap_or_else(|| panic!("{rows:#?}"));
        assert!(added.contains("END"), "panning reaches the end of the line: {added:?}");
        state.on_key(key(KeyCode::Char('w')));
        let rows = screen(&draw(&mut state, 60, 16));
        assert!(rows.iter().any(|r| r.contains("END")) && !rows.iter().any(|r| r.contains('›')), "{rows:#?}");
    }

