    fn terminal_escapes_in_file_content_are_shown_never_emitted() {
        let mut state = state();
        let diff = "--- a/e.txt\n+++ b/e.txt\n@@ -1 +1 @@\n-plain\n+\u{1b}]52;c;aGk=\u{7}\u{1b}[2Jgone\u{9b}x";
        feed_owned(&mut state, edit("c1", "e1", "e.txt", diff, ""));
