    }

    #[test]
    fn a_large_edit_is_bounded_with_an_exact_omission_count_and_the_review_shortcut() {
        let mut diff = String::from("--- a/big.txt\n+++ b/big.txt\n@@ -1,0 +1,62 @@\n");
        for i in 1..=37 {
            diff.push_str(&format!("+line {i}\n"));
