    new: &str,
    replace_all: bool,
    path: &str,
    accept: impl Fn(usize, usize) -> bool,
) -> Result<Option<(String, usize)>, String> {
    let positions: Vec<usize> = hay.match_indices(old).map(|(i, _)| i).filter(|&i| accept(i, i + old.len())).collect();
    if positions.is_empty() {
