let cached: BuildIdentity | null = null;

export function getBuildIdentity(): BuildIdentity {
  if (cached) return cached;
  let version = "1.2.1";
  try {
    const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, "cli/package.json"), "utf8"));
    if (pkg.version) version = pkg.version;
  } catch {}

  let commit = "unknown";
  let dirty = false;

  // Check if build_identity.json exists (e.g. from release packaging)
  const idPath = path.join(ROOT, "build_identity.json");
  if (fs.existsSync(idPath)) {
    try {
      const data = JSON.parse(fs.readFileSync(idPath, "utf8"));
      commit = data.commit ?? commit;
      dirty = Boolean(data.dirty);
      cached = {
        version,
        commit,
        dirty,
        string: `${version} (${commit}${dirty ? "-dirty" : ""})`,
      };
      return cached;
    } catch {}
  }

  // Try git
  try {
    const gitDir = path.join(ROOT, ".git");
    if (fs.existsSync(gitDir)) {
      commit = execSync("git rev-parse --short HEAD", { cwd: ROOT, stdio: ["ignore", "pipe", "ignore"], encoding: "utf8" }).trim();
      const status = execSync("git status --porcelain", { cwd: ROOT, stdio: ["ignore", "pipe", "ignore"], encoding: "utf8" }).trim();
      dirty = status.length > 0;
    }
  } catch {}

  cached = {
    version,
    commit,
    dirty,
    string: `${version}${commit !== "unknown" ? ` (${commit}${dirty ? "-dirty" : ""})` : ""}`,
  };
  return cached;
}
